/// 提供文字輸入、開關選項、帳戶類型切換、音量/進度範圍調節以及動態設定摘要之雙向資料綁定與命令邏輯。
/// </summary>
public partial class BasicControlsShowcaseViewModel : ObservableObject
{
    [ObservableProperty]
    private string _userName = "陳大明";

    [ObservableProperty]
    private string _email = "daming.chen@example.com";

    [ObservableProperty]
    private string _bio = "熱愛跨平台開發與 Avalonia 現代化介面架構設計。";

    [ObservableProperty]
    private bool _isDarkMode = true;

    [ObservableProperty]
    private bool _receiveNotifications = true;

    [ObservableProperty]
    private bool _isPersonalAccount = true;

    [ObservableProperty]
    private bool _isEnterpriseAccount = false;

    [ObservableProperty]
    private string _volumeLabel = "系統主音量 (85%)：";

    [ObservableProperty]
    private double _volumeValue = 85;

    [ObservableProperty]
    private string _progressLabel = "雲端同步進度 (75%)：";

    [ObservableProperty]
    private double _progressValue = 75;

    [ObservableProperty]
    private string _statusSummary = "使用者：陳大明 (daming.chen@example.com) | 主題：深色模式 | 通知：已開啟 | 帳戶：個人帳戶 | 音量：85% | 進度：75%";

    /// <summary>
    /// 當音量拉桿數值變更時，即時更新音量顯示標籤百分比。
    /// </summary>
    partial void OnVolumeValueChanged(double value)
    {
        VolumeLabel = $"系統主音量 ({value:F0}%)：";
    }

    /// <summary>
    /// 當進度條數值變更時，即時更新進度顯示標籤百分比。
    /// </summary>
    partial void OnProgressValueChanged(double value)
    {
        ProgressLabel = $"雲端同步進度 ({value:F0}%)：";
    }

    /// <summary>
    /// 當切換為個人帳戶時，自動取消選取企業帳戶。
    /// </summary>
    partial void OnIsPersonalAccountChanged(bool value)
    {
        if (value && IsEnterpriseAccount)
        {
            IsEnterpriseAccount = false;
        }
    }

    /// <summary>
    /// 當切換為企業帳戶時，自動取消選取個人帳戶。
    /// </summary>
    partial void OnIsEnterpriseAccountChanged(bool value)
    {
        if (value && IsPersonalAccount)
        {
            IsPersonalAccount = false;
        }
    }

    /// <summary>
    /// 收集目前所有控制項數值並進行格式檢核，動態產出帶有時間戳記的即時設定摘要字串。
    /// </summary>
    [RelayCommand]
    private async Task SaveSettingsAsync()
    {
        await Task.Delay(50);
        var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");

        // 欄位基礎驗證
        if (string.IsNullOrWhiteSpace(UserName))
        {
            StatusSummary = $"[{timestamp}] ⚠️ 儲存失敗：使用者名稱不可為空！";
            return;
        }

        if (string.IsNullOrWhiteSpace(Email) || !Email.Contains('@') || !Email.Contains('.'))
        {
            StatusSummary = $"[{timestamp}] ⚠️ 儲存失敗：電子郵件格式無效 ({Email})！";
            return;
        }

        var theme = IsDarkMode ? "深色模式" : "淺色模式";
        var notifications = ReceiveNotifications ? "已開啟" : "已關閉";
        var accountType = IsPersonalAccount ? "個人帳戶" : (IsEnterpriseAccount ? "企業帳戶" : "未指定");
        var bioBrief = string.IsNullOrWhiteSpace(Bio) ? "未填寫" : (Bio.Length > 20 ? Bio[..20] + "..." : Bio);

        StatusSummary = $"[{timestamp}] ✅ 偏好設定儲存成功 | 使用者：{UserName} ({Email}) | 主題：{theme} | 通知：{notifications} | 帳戶：{accountType} | 音量：{VolumeValue:F0}% | 進度：{ProgressValue:F0}% | 簡介：{bioBrief}";
    }

    /// <summary>
    /// 重設所有輸入欄位與控制項狀態至預設值，並更新即時設定摘要。
    /// </summary>
    [RelayCommand]
    private async Task ResetSettingsAsync()
    {
        await Task.Delay(50);
        UserName = "陳大明";
        Email = "daming.chen@example.com";
        Bio = "熱愛跨平台開發與 Avalonia 現代化介面架構設計。";
        IsDarkMode = true;
        ReceiveNotifications = true;
        IsPersonalAccount = true;
        IsEnterpriseAccount = false;
        VolumeValue = 85;
        ProgressValue = 75;

        var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
        StatusSummary = $"[{timestamp}] 🔄 設定已重設為預設值 | 使用者：陳大明 (daming.chen@example.com) | 主題：深色模式 | 通知：已開啟 | 帳戶：個人帳戶 | 音量：85% | 進度：75%";
    }
}
